// Parser for ebusd message definition files (CSV), as generated by
// ebus-typespec and served on https://ebus.github.io/ (see ebusd
// src/lib/ebus/message.cpp: Message::create, MessageMap::readFromStream).

import { isMaster } from '../ebus/address.ts';
import { splitCsvLine, splitLines } from './csv.ts';
import { parseCheck, splitConditions, type ConditionDef, type ConditionRef } from './conditions.ts';
import { createFields, type FieldColumns, type FieldDef } from './fields.ts';

export type MessageType = 'r' | 'w' | 'u' | 'uw';

export interface MessageDef {
  /** Path of the defining file, e.g. "vaillant/08.hmu.csv". */
  file: string;
  line: number;
  type: MessageType;
  pollPriority: number;
  circuit: string;
  level?: string;
  name: string;
  comment?: string;
  qq?: number;
  /** Target addresses; undefined = any. */
  zz?: number[];
  pb: number;
  sb: number;
  /** ID bytes after PB SB (first chain part for chained messages). */
  id: number[];
  /** Chained message: several IDs whose slave data is concatenated. */
  chain?: number[][];
  fields: FieldDef[];
  conditions: ConditionRef[];
  /** Set for definitions from local files (DEC-6). */
  local?: boolean;
}

export interface LoadDirective {
  file: string;
  conditions: ConditionRef[];
  line: number;
}

export interface DefinitionFile {
  path: string;
  messages: MessageDef[];
  conditions: ConditionDef[];
  loads: LoadDirective[];
  errors: Array<{ line: number; message: string }>;
}

export interface FileDefaults {
  /** Target address from the file name (two hex digits). */
  zz?: string;
  /** Circuit name from the file name. */
  circuit?: string;
}

const DEFAULT_HEADER = ['type', 'circuit', 'level', 'name', 'comment', 'qq', 'zz', 'pbsb', 'id', '*name', 'part', 'type', 'divisor/values', 'unit', 'comment'];

type MessageColumns = Partial<Record<'circuit' | 'level' | 'name' | 'comment' | 'qq' | 'zz' | 'pbsb' | 'id', string>>;

function parseHexBytes(s: string, what: string): number[] {
  const clean = s.replace(/\s+/g, '');
  if (clean.length % 2 !== 0 || !/^[0-9a-f]*$/i.test(clean)) throw new Error(`invalid ${what} "${s}"`);
  const out: number[] = [];
  for (let i = 0; i < clean.length; i += 2) out.push(parseInt(clean.slice(i, i + 2), 16));
  return out;
}

function parseAddress(s: string, what: string): number {
  const b = parseHexBytes(s, what);
  if (b.length !== 1) throw new Error(`invalid ${what} "${s}"`);
  return b[0]!;
}

/** Parses one definition file. Errors are collected per line; parsing continues. */
export function parseDefinitionFile(text: string, path: string, fileDefaults: FileDefaults = {}, opts: { local?: boolean; inheritedConditions?: ConditionRef[] } = {}): DefinitionFile {
  const result: DefinitionFile = { path, messages: [], conditions: [], loads: [], errors: [] };
  let header = DEFAULT_HEADER;
  const typeDefaults = new Map<string, MessageColumns>();
  const fileZz = fileDefaults.zz ? parseInt(fileDefaults.zz, 16) : undefined;

  const lines = splitLines(text);
  lines.forEach((rawLine, idx) => {
    const lineNo = idx + 1;
    const line = rawLine.trim();
    if (!line || line.startsWith('#') || line.startsWith('//')) return;
    const cols = splitCsvLine(rawLine);
    if (cols[0]!.trim().toLowerCase() === 'type') {
      header = cols.map((c) => c.trim().toLowerCase());
      return;
    }
    try {
      const star = header.findIndex((h) => h.startsWith('*'));
      const msgHeader = star >= 0 ? header.slice(0, star) : header;
      const fieldHeader = star >= 0 ? header.slice(star).map((h, i) => (i === 0 ? h.slice(1) : h)) : [];
      const msg: MessageColumns = {};
      msgHeader.forEach((h, i) => {
        if (i > 0 && h) (msg as Record<string, string>)[h] = (cols[i] ?? '').trim();
      });

      const { refs, rest } = splitConditions(cols[0]!);
      const all = [...(opts.inheritedConditions ?? []), ...refs];

      if (rest.startsWith('*[')) {
        // condition definition: *[name],circuit,,message,,field,zz,values
        const name = /^\*\[([A-Za-z0-9_]+)\]$/.exec(rest)?.[1];
        if (!name) throw new Error(`invalid condition definition "${rest}"`);
        const def: ConditionDef = {
          name,
          circuit: msg.circuit ?? '',
          message: msg.name ?? '',
          field: msg.qq ?? '',
        };
        if (msg.zz) def.zz = parseAddress(msg.zz, 'zz');
        if (msg.pbsb) def.check = parseCheck(msg.pbsb);
        if (fileDefaults.circuit) def.fileCircuit = fileDefaults.circuit;
        if (fileZz !== undefined) def.fileZz = fileZz;
        result.conditions.push(def);
        return;
      }
      if (rest.startsWith('*')) {
        typeDefaults.set(rest.slice(1).toLowerCase(), msg);
        return;
      }
      if (rest.toLowerCase() === '!load' || rest.toLowerCase() === '!include') {
        const file = (cols[1] ?? '').trim();
        if (!file) throw new Error('missing file name');
        result.loads.push({ file, conditions: all, line: lineNo });
        return;
      }
      if (rest.startsWith('!')) throw new Error(`unsupported directive "${rest}"`);

      const def = parseMessage(rest, msg, typeDefaults, fileDefaults, fileZz, cols.slice(star >= 0 ? star : header.length), fieldHeader);
      def.file = path;
      def.line = lineNo;
      def.conditions = all;
      if (opts.local) def.local = true;
      result.messages.push(def);
    } catch (err) {
      result.errors.push({ line: lineNo, message: err instanceof Error ? err.message : String(err) });
    }
  });
  return result;
}

function parseMessage(
  typeStr: string,
  row: MessageColumns,
  typeDefaults: Map<string, MessageColumns>,
  fileDefaults: FileDefaults,
  fileZz: number | undefined,
  fieldCols: string[],
  fieldHeader: string[],
): MessageDef {
  const lower = typeStr.toLowerCase();
  if (!lower) throw new Error('empty type');
  let type: MessageType;
  let pollPriority = 0;
  let defaultsKey = lower;
  if (lower[0] === 'r') {
    type = 'r';
    if (/^r\d$/.test(lower)) {
      pollPriority = Number(lower[1]);
      defaultsKey = 'r';
    }
  } else if (lower[0] === 'w') type = 'w';
  else type = lower[1] === 'w' ? 'uw' : 'u';
  const isWrite = type === 'w' || type === 'uw';
  const defaults = typeDefaults.get(defaultsKey) ?? {};
  const get = (k: keyof MessageColumns) => row[k] || defaults[k] || '';

  let circuit = get('circuit') || fileDefaults.circuit || '';
  let level = get('level');
  const hash = circuit.indexOf('#');
  if (hash >= 0) {
    level = circuit.slice(hash + 1);
    circuit = circuit.slice(0, hash);
  }
  if (!circuit) throw new Error('missing circuit');
  const name = row.name ?? '';
  if (!name) throw new Error('missing name');

  const def: MessageDef = {
    file: '',
    line: 0,
    type,
    pollPriority,
    circuit,
    name,
    pb: 0,
    sb: 0,
    id: [],
    fields: [],
    conditions: [],
  };
  if (level) def.level = level;
  const comment = get('comment');
  if (comment) def.comment = comment;

  const qq = get('qq');
  if (qq) {
    def.qq = parseAddress(qq, 'qq');
    if (!isMaster(def.qq)) throw new Error(`qq ${qq} is not a master address`);
  }
  const zzStr = get('zz');
  if (zzStr) def.zz = zzStr.split(';').map((z) => parseAddress(z.trim(), 'zz'));
  else if (fileZz !== undefined) def.zz = [fileZz];
  const masterDestination = !!def.zz && def.zz.length > 0 && (def.zz[0] === 0xfe || isMaster(def.zz[0]!));

  let pbsbStr = row.pbsb ?? '';
  let idPrefix = '';
  if (!pbsbStr) {
    pbsbStr = defaults.pbsb ?? '';
    idPrefix = defaults.id ?? '';
  }
  const pbsb = parseHexBytes(pbsbStr, 'pbsb');
  if (pbsb.length !== 2) throw new Error(`invalid pbsb "${pbsbStr}"`);
  def.pb = pbsb[0]!;
  def.sb = pbsb[1]!;
  const ids = (row.id ?? '').split(';').map((part) => parseHexBytes(idPrefix + part.trim().replace(/:\d+$/, ''), 'id'));
  def.id = ids[0]!;
  if (ids.length > 1) {
    if (type === 'u' || type === 'uw') throw new Error('chained passive message');
    def.chain = ids;
  }

  // fields: groups of the field columns
  const size = fieldHeader.length || 6;
  for (let i = 0; i < fieldCols.length; i += size) {
    const group = fieldCols.slice(i, i + size);
    if (group.every((c) => c.trim() === '')) continue;
    const g: Record<string, string> = {};
    (fieldHeader.length ? fieldHeader : DEFAULT_HEADER.slice(9).map((h, j) => (j === 0 ? 'name' : h))).forEach((h, j) => {
      g[h] = group[j] ?? '';
    });
    const cols: FieldColumns = {
      name: g.name ?? '',
      part: g.part ?? '',
      type: g.type ?? '',
      divisorValues: g['divisor/values'] ?? g.divisor ?? g.values ?? '',
      unit: g.unit ?? '',
      comment: g.comment ?? '',
    };
    try {
      def.fields.push(...createFields(cols, isWrite, masterDestination));
    } catch (err) {
      throw new Error(`field ${i / size + 1} (${cols.name || cols.type}): ${err instanceof Error ? err.message : String(err)}`);
    }
  }
  return def;
}
